CREATE DATABASE IF NOT EXISTS `academic_studio` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE `academic_studio`;
CREATE TABLE IF NOT EXISTS users (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NULL,password_hash VARCHAR(255) NULL,role ENUM('admin','staff') NOT NULL DEFAULT 'staff',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS teachers (id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,subject VARCHAR(100) NULL,phone VARCHAR(30) NULL,whatsapp VARCHAR(30) NULL,fee DECIMAL(14,2) NOT NULL DEFAULT 0,notes TEXT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS schedules (id INT AUTO_INCREMENT PRIMARY KEY,teacher_id INT NOT NULL,title VARCHAR(180) NOT NULL,start_at DATETIME NOT NULL,end_at DATETIME NULL,status ENUM('scheduled','done','cancelled') NOT NULL DEFAULT 'scheduled',notes TEXT NULL,reminder_sent TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(start_at),INDEX(teacher_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS transactions (id INT AUTO_INCREMENT PRIMARY KEY,type ENUM('income','expense','teacher_payment') NOT NULL,teacher_id INT NULL,amount DECIMAL(14,2) NOT NULL DEFAULT 0,description VARCHAR(255) NULL,transaction_date DATE NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(transaction_date),INDEX(type),INDEX(teacher_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS settings (id INT PRIMARY KEY,studio_name VARCHAR(150) NOT NULL DEFAULT 'استوديو أكاديمي',backup_email VARCHAR(190) NULL,studio_whatsapp VARCHAR(30) NULL,currency VARCHAR(20) NOT NULL DEFAULT 'د.ع',updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO settings(id,studio_name,currency) VALUES(1,'استوديو أكاديمي','د.ع') ON DUPLICATE KEY UPDATE id=id;
